import json
import re

WEIGHTS = (7, 3, 1)


def char_value(ch):
    if ch == '<':
        return 0
    if '0' <= ch <= '9':
        return ord(ch) - ord('0')
    if 'A' <= ch <= 'Z':
        return ord(ch) - ord('A') + 10
    raise ValueError('invalid MRZ character')


def valid_digit(data, digit, allow_empty=False):
    if allow_empty and digit == '<' and set(data) <= {'<'}:
        return True
    return digit.isdigit() and sum(char_value(ch) * WEIGHTS[i % 3] for i, ch in enumerate(data)) % 10 == int(digit)


def clean(value):
    return value.replace('<', ' ').strip()


def names(value):
    parts = value.split('<<', 1)
    return {'surname': clean(parts[0]), 'given_names': clean(parts[1]) if len(parts) == 2 else ''}


def response(error, failed=None):
    body = {'valid': False, 'error': error, 'attributes': None}
    if failed:
        body['failed_checks'] = failed
    return json.dumps(body, ensure_ascii=False, separators=(',', ':'))


def parse_input(raw):
    if not isinstance(raw, str):
        return []
    match = re.search(r'\{[\s\S]*\}', raw)
    if not match:
        return []
    try:
        value = json.loads(match.group(0)).get('mrz_lines', [])
    except (ValueError, TypeError, AttributeError):
        return []
    if not isinstance(value, list):
        return []
    return [str(line).strip().upper() for line in value]


def document_number(primary, fixed_digit, optional):
    if fixed_digit.isdigit():
        return clean(primary), ('document_number', primary, fixed_digit), optional
    if fixed_digit != '<':
        return None
    filler = optional.find('<')
    if filler < 1:
        return None
    encoded = optional[:filler]
    continuation, digit = encoded[:-1], encoded[-1]
    if not continuation or not digit.isdigit():
        return None
    return clean(primary + continuation), ('document_number', primary + continuation, digit), optional[filler + 1:]


def main(ocr_result):
    lines = parse_input(ocr_result)
    if not lines:
        return response('mrz_not_found')
    if any(not re.fullmatch(r'[A-Z0-9<]+', line) for line in lines):
        return response('invalid_mrz_characters')

    if len(lines) == 2 and all(len(line) == 44 for line in lines):
        kind = 'TD3'
        a, b = lines
        checks = [
            ('document_number', b[0:9], b[9]),
            ('birth_date', b[13:19], b[19]),
            ('expiry_date', b[21:27], b[27]),
            ('optional_data', b[28:42], b[42], True),
            ('composite', b[0:10] + b[13:20] + b[21:43], b[43])
        ]
        attrs = {'document_code': clean(a[0:2]), 'issuing_state': a[2:5], **names(a[5:44]), 'document_number': clean(b[0:9]), 'nationality': b[10:13], 'birth_date': b[13:19], 'sex': clean(b[20]), 'expiry_date': b[21:27], 'optional_data': clean(b[28:42])}
    elif len(lines) == 2 and all(len(line) == 36 for line in lines):
        kind = 'TD2'
        a, b = lines
        parsed_number = document_number(b[0:9], b[9], b[28:35])
        if parsed_number is None:
            return response('invalid_document_number_encoding')
        number, number_check, remaining_optional = parsed_number
        checks = [number_check, ('birth_date', b[13:19], b[19]), ('expiry_date', b[21:27], b[27]), ('composite', b[0:10] + b[13:20] + b[21:35], b[35])]
        attrs = {'document_code': clean(a[0:2]), 'issuing_state': a[2:5], **names(a[5:36]), 'document_number': number, 'nationality': b[10:13], 'birth_date': b[13:19], 'sex': clean(b[20]), 'expiry_date': b[21:27], 'optional_data': clean(remaining_optional)}
    elif len(lines) == 3 and all(len(line) == 30 for line in lines):
        kind = 'TD1'
        a, b, c = lines
        parsed_number = document_number(a[5:14], a[14], a[15:30])
        if parsed_number is None:
            return response('invalid_document_number_encoding')
        number, number_check, remaining_optional = parsed_number
        checks = [number_check, ('birth_date', b[0:6], b[6]), ('expiry_date', b[8:14], b[14]), ('composite', a[5:30] + b[0:7] + b[8:15] + b[18:29], b[29])]
        attrs = {'document_code': clean(a[0:2]), 'issuing_state': a[2:5], 'document_number': number, 'optional_data': clean(remaining_optional + b[18:29]), 'birth_date': b[0:6], 'sex': clean(b[7]), 'expiry_date': b[8:14], 'nationality': b[15:18], **names(c)}
    else:
        return response('unsupported_mrz_layout')

    failed = []
    for check in checks:
        name, value, digit, *options = check
        if not valid_digit(value, digit, *options):
            failed.append(name)
    if failed:
        return response('checksum_failed', failed)
    return json.dumps({'valid': True, 'format': kind, 'attributes': attrs}, ensure_ascii=False, separators=(',', ':'))

